<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Bootstrap\Plugin;

use DI\Container;
use Override;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Psr\Log\LoggerInterface;
use Psr\Log\NullLogger;
use Slim\Psr7\Response;
use Slim\Middleware\ErrorMiddleware;
use Slim\Exception\HttpMethodNotAllowedException;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Exception\InsufficientUserAuthenticationException;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;

/**
 * Registers HTTP error handlers for common domain exceptions.
 */
class ErrorsPlugin extends MicroPlugin
{
    private LoggerInterface $logger;

    public function __construct()
    {
        $this->logger = new NullLogger();
    }

    #[Override]
    public function bindServices(Container $container): void
    {
        if ($container->has(LoggerInterface::class)) {
            $this->logger = $container->get(LoggerInterface::class);
        }
        parent::bindServices($container);
    }

    /**
     * Configures error handlers for validation and auth failures.
     */
    #[Override]
    public function registerErrorHandler(ErrorMiddleware $errorHandler): void
    {
        $errorHandler->setErrorHandler(ConstraintException::class, function (ServerRequestInterface $request, ConstraintException $exception): ResponseInterface {
            $errors = [];
            foreach ($exception as $fail) {
                foreach ($fail->fields as $k => $field) {
                    $errors[$field] = [ $fail->wrongValues[$k] . ' fail for ' . $fail->code . '' ];
                }
            }
            $content = [
                "type" => "/validation-error",
                "title" => "Validation failed",
                "status" => 422,
                "errors" => $errors
            ];
            $response = new Response();
            $json = json_encode($content);
            $response->getBody()->write($json !== false ? $json : '{}');
            return $response->withStatus(422)->withHeader("Content-Type", "application/problem+json");
        });
        $logger = $this->logger;
        $errorHandler->setErrorHandler(InsufficientUserAuthenticationException::class, function (ServerRequestInterface $request, InsufficientUserAuthenticationException $exception) use ($logger): ResponseInterface {
            $logger->info('401 InsufficientUserAuthenticationException', [
                'message' => $exception->getMessage(),
                'path' => $request->getUri()->getPath(),
                'acr' => $exception->acrValues,
                'maxAge' => $exception->maxAge,
            ]);
            $response = new Response();
            $json = json_encode([
                'error' => 'insufficient_user_authentication',
                'message' => $exception->getMessage(),
                'acr_values' => $exception->acrValues,
                'max_age' => $exception->maxAge,
            ]);
            $response->getBody()->write($json !== false ? $json : '{}');
            // RFC 9470 §3: the client asks the user to authenticate again with these values.
            return $response->withStatus(401)
                ->withHeader('Content-Type', 'application/json')
                ->withHeader('WWW-Authenticate', $exception->challenge());
        });
        $errorHandler->setErrorHandler(UnauthorizedException::class, function (ServerRequestInterface $request, UnauthorizedException $exception) use ($logger): ResponseInterface {
            $logger->warning('401 UnauthorizedException', [
                'message' => $exception->getMessage(),
                'path' => $request->getUri()->getPath(),
                'trace' => $exception->getTraceAsString(),
            ]);
            $response = new Response();
            $data = [
                'message' => $exception->getMessage()
            ];
            $json = json_encode($data);
            $response->getBody()->write($json !== false ? $json : '{}');
            $response = $response->withStatus(401);
            // RFC 6750 §3: a rejected bearer token is challenged as such.
            return preg_match('/^Bearer\s/i', $request->getHeaderLine('Authorization'))
                ? $response->withHeader('WWW-Authenticate', 'Bearer error="invalid_token"')
                : $response;
        });
        $errorHandler->setErrorHandler(HttpMethodNotAllowedException::class, function (ServerRequestInterface $request, HttpMethodNotAllowedException $exception): ResponseInterface {
            $response = new Response();
            $data = [
                'message' => $exception->getMessage()
            ];
            $json = json_encode($data);
            $response->getBody()->write($json !== false ? $json : '{}');
            return $response->withStatus(404);
        });
    }
}
